(1,	1,	'BK20251123KAI7',	1,	'QT2509008',	NULL,	NULL,	NULL,	NULL,	NULL,	0,	NULL,	'incentive-groups',	'cancelled',	'2025-11-23 13:53:13',	'2025-11-23 14:57:19',	NULL,	NULL,	NULL,	NULL,	'2025-11-14',	'2025-11-15',	NULL,	NULL,	1,	1,	2,	0,	'[\"NNNNNNNNN\", \"NNNNNNNNNNNNNN\", \"NNNNNNNNNNNNNNNNNN\"]',	'PKG25022',	NULL,	'SSSSSSSSS\r\nSSSSSSSSSSSSSSSSS\r\nSSSSSSSSSSSSSSSSSSSSSSS',	'AAAAAAAAAAAA\r\nAAAAAAAAAAAAAAAA',	'MMMMMMMM\r\nMMMMMMMMMMMM',	NULL,	NULL,	NULL,	'SSSSSSSSSSS\r\nSSSSSSSSSSSSSSSS',	'Hong Kong',	NULL,	'12:30:00',	NULL,	'NOTES  \r\nTTTTTTTTTT\r\nTTTTTTTTTTTTTTTTTTTTT',	'<p>FFFFFFFFFFFFFFF<br>FFFFFFFFFFFFFFFFFFFFFFFFF</p>',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 1, \"price\": 2000.0, \"amount\": 2000.0}, {\"name\": \"CHD\", \"quantity\": 1, \"price\": 500.0, \"amount\": 500.0}]',	2500.00,	'THB',	'2025-11-12 12:00:00',	'2025-12-23',	'2025-11-23 13:38:13',	'2025-11-27 06:18:41',	'MXwxNzY0MjI0MjkwfDR8MTc3MzUzMjgwMC4YsUMbPvhDtx0R3-dF1nbA9lQizsl04PlUkA',	4,	3,	NULL,	NULL),
(2,	1,	'QT3CE50B0A',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	0,	NULL,	'tour',	'Quoted',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'2025-11-24',	'2025-11-30',	NULL,	NULL,	2,	0,	2,	0,	NULL,	'',	NULL,	'แพคเกจ มาเก๊า Chimelong 4วัน 3คืน\r\n\r\n28DEC : กรุงเทพฯ-มาเก๊า\r\n07:30น. เช็คอินสนามบินสุวรรณภูมิ สายการบิน Air Macau\r\n10:35น. บินจากกรุงเทพฯสู่มาเก๊า เที่ยวบิน NX995\r\n14:25น. ถึงสนามบินมาเก๊า ผ่านด่านตรวจคนเข้าเมือง รับกระเป๋า \r\nเดินทางสู่โรงแรมที่พัก โดย Shuttle Bus ของโรงแรม \r\nพักที่ Gand Lisboa Palace\r\n*รวมบัตรขึ้นกระเช้า Golden Reel (ไม่รวมรถบริการ)\r\n------------\r\n29DEC : มาเก๊า\r\nเช้า บริการอาหารเช้า แบบบุฟเฟต์ อิสระท่องเที่ยวมาเก๊า\r\nพักที่ Gand Lisboa Palace\r\n------------\r\n30DEC : มาเก๊า-จูไห่ \r\nเช้า บริการอาหารเช้า แบบบุฟเฟต์\r\nตามเวลานัดหมาย รถรับคณะจากโรงแรมมาเก๊า ส่งที่ Chimelong Spaceship Hotel \r\nรวมบัตรเข้า Spaceship Park (Unlimited) \r\nบริการอาหารเย็นบุเฟต์*** \r\nพักที่ Chimelong Spaceship Hotel\r\n------------\r\n31DEC : จูไห่-มาเก๊า-กรุงเทพฯ\r\nบริการอาหารเช้าบุเฟต์***\r\nบัตรเข้า Spaceship Park (Unlimited) \r\nตามเวลานัดหมาย รถรับคณะจาก Chimelong Spaceship Hotel ส่งสนามบินมาเก๊า \r\nเช็คอินสนามบินสุวรรณภูมิ สายการบิน Air Macau\r\n19:50น. บินจากสนามบินมาเก๊า สู่สนามบินสุวรรณภูมิ เที่ยวบิน NX992\r\n21:50น. ถึงกรุงเทพฯ โดยสวัสดิภาพและความประทับใจ',	NULL,	NULL,	NULL,	NULL,	NULL,	'None',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[]',	0.00,	'THB',	'2025-11-26 14:10:00',	NULL,	'2025-11-23 14:10:33',	'2025-11-29 02:07:19',	'MnwxNzY0MzgyMDg0fDF8MTc3NDgyODgwMC4EyBBIfkIdakyOeWBQltsgbkI76ElEzvurXg',	1,	NULL,	NULL,	NULL),
