(28,	13,	'251126U1CD',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'package',	'draft',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'2025-12-04',	'2025-12-07',	NULL,	NULL,	2,	1,	3,	0,	'[\"N/A\"]',	'Jirawat20251204-07',	NULL,	'Chimelong Macau Daily Special 3Nights 4Days\r\nเดินทาง 4-7 | 6-9 DEC.2025 \r\nสำหรับ 2ผู้ใหญ่ 1เด็ก \r\n\r\nPlan1: เดินทาง 4-7DEC2025 (พักมาเก๊าคืนแรก)\r\nDay1: กรุงเทพฯ-มาเก๊า\r\nถึงสนามบินมาเก๊า เดินทางสู่โรงแรม Studio City ให้บริการโดยโรงแรม\r\nอิสระ กิจกรรมตามอัธยาศัย\r\nพักที่ Studio City Macau\r\n------\r\nDay2: รวมบุฟเฟต์อาหารเช้า***\r\nตามเวลานัดหมาย รถส่วนตัว** รับจากโรงแรม Studio City\r\nเดินทางสู่ Chimelong Spaceship Hotel\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\n+เย็น ชมแกรนด์โชว์ Chimelong Hengqin\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay3: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay4: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nตามเวลานัดหมาย*รถส่วนตัวคณะเดินทางสู่สนามบินมาเก๊า\r\n\r\nเดินทาง 4-7 DEC 2025\r\nสายการบิน Lion Air รวมน้ำหนักเฉพาะผู้ใหญ่ 20กก\r\nSL372 04DEC DMKMFM 1010-1350\r\nSL373 07DEC MFMDMK 1445-1625\r\nผู้ใหญ่ 25,900 บ x 2ท่าน  เด็ก 23,900 x 1 ท่าน\r\n\r\n================\r\n\r\nPlan2: เดินทาง 6-9DEC2025 (พักมาเก๊าคืนที่สาม)\r\nDay1: กรุงเทพฯ-มาเก๊า\r\nถึงสนามบินมาเก๊า รถส่วนตัว **นำท่านเดินทางสู่ Chimelong Spaceship Hotel\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\n+เย็น ชมแกรนด์โชว์ Chimelong Hengqin\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay2: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay3: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nตามเวลานัดหมาย*รถส่วนตัวคณะเดินทางสู่โรงแรมมาเก๊า\r\nพักที่ Studio City Macau\r\n------\r\nDay4: รวมบุฟเฟต์อาหารเช้า***\r\nอิสระท่องเที่ยวมาเก๊า \r\nตามเวลาสมควรเดินทางสู่สนามบิน ให้บริการโดยโรงแรม\r\n\r\nเดินทาง 6-9 DEC 2025\r\nสายการบิน Air Macau *ฟูลเซอร์วิส น้ำหนักโหลด 32KG 1ใบ ทุกท่าน\r\nNX935 06DEC DMKMFM 0930-1300\r\nNX992 09DEC MFMDMK 1950-2150\r\nผู้ใหญ่ 24,900 บ x 2ท่าน  เด็ก 22,900 x 1 ท่าน\r\n\r\n>>ราคา ณ เวลานี้<<',	NULL,	NULL,	NULL,	NULL,	NULL,	'None',	'MFM',	NULL,	NULL,	NULL,	'4-7 DEC 2025 \r\n\r\nLion Air\r\nSL372 04DEC DMKMFM 10:10-13:50\r\nSL371 07DEC MFMDMK 22:05-23:50\r\nต้นทุน 16595 x3\r\n--หรือกลับบ่าย\r\nSL372 04DEC DMKMFM 10:10-13:50\r\nSL373 07DEC MFMDMK 14:45-16:25\r\nต้นทุน 9995 x3\r\n--------------\r\nAir Asia *กลับเช้า\r\nFD775 04DEC DMKMFM 06:45-10:20\r\nFD763 07DEC MFMDMK 10:50-12:45\r\nต้นทุน 8420 x3\r\n--------------\r\nAir Macau = ขากลับเต็มค่ะ\r\n\r\n------------------------------------------\r\n6-9 DEC 2025\r\n\r\nAir Asia\r\nFD775 06DEC DMKMFM 0645-1020\r\nFD765 09DEC MFMDMK 17:55-19:50\r\nต้นทุน 8420 x3\r\n--------------\r\nAir Macau \r\nNX935 06DEC DMKMFM 09:30-13:00\r\nNS992 09DEC MFMDMK 19:50-21:50\r\nต้นทุน 10,315 x2ADT / 8415 x1CHD\r\n--------------\r\nLion Air = ว่างแค่ไฟล์เย็น',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 1, \"price\": 0.0, \"amount\": 0.0}]',	0.00,	NULL,	'2025-11-27 12:00:00',	'2025-12-26',	'2025-11-26 10:07:42',	'2025-11-26 11:59:51',	NULL,	1,	4,	NULL,	NULL),
