(42,	24,	'251128DCF8',	NULL,	NULL,	NULL,	22,	NULL,	NULL,	NULL,	1,	'2025-11-28 07:05:42',	'package',	'vouchered',	'2025-11-28 07:05:09',	'2025-11-28 07:05:13',	NULL,	NULL,	'2025-11-28 07:05:46',	NULL,	'2025-12-28',	'2025-12-31',	NULL,	NULL,	6,	1,	7,	0,	'[\"TRIWANAKARN/TEERATAT MR\", \"SANGCHAN/JURAIPORN MS\", \"TRIWANAKARN/NACHAPAT MSTR (CHD/5Y)\", \"TRIWANAKARN/JEERANUCH MRS\", \"TRIWANAKARN/TANYAPORN MISS\", \"TRIWANAKARN/KARUN MR\", \"TRIWANAKARN/TANAKORN MR\"]',	'AR0388526',	NULL,	'แพคเกจ มาเก๊า Chimelong 4วัน 3คืน',	NULL,	NULL,	NULL,	NULL,	NULL,	'None',	'MFM',	NULL,	NULL,	NULL,	'แพคเกจ มาเก๊า Chimelong 4วัน 3คืน\r\n\r\n28DEC : กรุงเทพฯ-มาเก๊า\r\n07:30น. เช็คอินสนามบินสุวรรณภูมิ สายการบิน Air Macau\r\n10:35น. บินจากกรุงเทพฯสู่มาเก๊า เที่ยวบิน NX995\r\n14:25น. ถึงสนามบินมาเก๊า ผ่านด่านตรวจคนเข้าเมือง รับกระเป๋า \r\nเดินทางสู่โรงแรมที่พัก โดย Shuttle Bus ของโรงแรม \r\nพักที่ Gand Lisboa Palace\r\n*รวมบัตรขึ้นกระเช้า Golden Reel (ไม่รวมรถบริการ)\r\n------------\r\n29DEC : มาเก๊า\r\nเช้า บริการอาหารเช้า แบบบุฟเฟต์ อิสระท่องเที่ยวมาเก๊า\r\nพักที่ Gand Lisboa Palace\r\n------------\r\n30DEC : มาเก๊า-จูไห่ \r\nเช้า บริการอาหารเช้า แบบบุฟเฟต์\r\nตามเวลานัดหมาย รถรับคณะจากโรงแรมมาเก๊า ส่งที่ Chimelong Spaceship Hotel \r\nรวมบัตรเข้า Spaceship Park (Unlimited) \r\nบริการอาหารเย็นบุเฟต์*** \r\nพักที่ Chimelong Spaceship Hotel\r\n------------\r\n31DEC : จูไห่-มาเก๊า-กรุงเทพฯ\r\nบริการอาหารเช้าบุเฟต์***\r\nบัตรเข้า Spaceship Park (Unlimited) \r\nตามเวลานัดหมาย รถรับคณะจาก Chimelong Spaceship Hotel ส่งสนามบินมาเก๊า \r\nเช็คอินสนามบินสุวรรณภูมิ สายการบิน Air Macau\r\n19:50น. บินจากสนามบินมาเก๊า สู่สนามบินสุวรรณภูมิ เที่ยวบิน NX992\r\n21:50น. ถึงกรุงเทพฯ โดยสวัสดิภาพและความประทับใจ',	'<p>NX 995 28DEC BKKMFM 10:35-14:25<br>NX 992 31DEC MFMBKK  19:50-21:50</p>',	'[{\"arrival\": \"28/12/2025\", \"departure\": \"31/12/2025\", \"service_by\": \"Dhakul Chan Nice Holidays\", \"type\": \"Macau-Chimelong 3N4D\"}]',	NULL,	'[]',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 6, \"price\": 30900.0, \"amount\": 185400.0}, {\"name\": \"CHD No Bed\", \"quantity\": 1, \"price\": 28900.0, \"amount\": 28900.0}]',	214300.00,	NULL,	'2025-11-29 12:00:00',	'2025-12-28',	'2025-11-28 07:04:39',	'2025-11-29 01:58:51',	'NDJ8MTc2NDMxMzQ4M3wxfDE3Nzc1MDcyMDAuwglORrBqrB7zjNFGctZEuYE9r_FXNKpVh14',	1,	4,	NULL,	NULL),
