(45,	27,	'251129X1L6',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'package',	'draft',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'2025-12-28',	'2025-12-31',	NULL,	NULL,	2,	1,	3,	0,	'N.A.',	'',	NULL,	'Macau Chimelong daily Special \r\nเดินทาง 28-31 ธันวาคม 2568\r\nผู้ใหญ่ 2 เด็ก 1\r\nDay1: กรุงเทพฯ-มาเก๊า\r\nถึงสนามบินมาเก๊า เดินทางเข้าสู่ที่พักให้บริการโดยโรงแรม\r\nพักมาเก๊า  Studio City หรือ Broadway Hotel\r\n======\r\nDay2: ตามเวลานัดหมายรถส่วนตัวรับจาก Studio City หรือ Broadway Hotel ส่ง Chimelong Spaceship Hotel \r\n+บัตรเข้า Chimelong Spaceship Park\r\n+บัตรเข้า Chimelong Ocean Kingdom\r\n+บัตรชมโชว์ Chimelong Hengqin\r\n+บุฟเฟต์อาหารเย็น พัก Chimelong Spaceship Hotel\r\n======\r\nDay3: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง\r\n+บุฟเฟต์อาหารเช้า \r\nบัตรเข้า Chimelong Spaceship Park\r\nบัตรเข้า Chimelong Ocean Kingdom\r\nพัก Chimelong Spaceship Hotel\r\n\r\nDay4: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง \r\n+บุฟเฟต์อาหารเช้า \r\nบัตรเข้า Chimelong Spaceship Park\r\nบัตรเข้า Chimelong Ocean Kingdom\r\nตามเวลานัดหมายรถส่วนตัวรับจาก Chimelong Spaceship Hotel ส่งสนามมบินมาเก๊า\r\n=======\r\nเดินทาง 28-31ธันวาคม  โดยเที่ยวบิน Lion Air\r\n*น้ำหนักโหลด 20KG 1ใบ เฉพาะผู้ใหญ่* และ Carry on 7 KG  ทุกท่าน \r\nSL372 28DEC DMKMFM 10:10-13:50\r\nSL371  31DEC MFMDMK 22:05-23:50\r\nมาเก๊าพัก Studio City หรือ Broadway \r\nผู้ใหญ่ 28,900 บ/ท่าน x 2\r\nเด็ก 26,900 บ/ท่าน x 1 ไม่มีเตียงเสริม \r\n<<<ราคา ณ เวลานี้ พร้อมออกตั๋วทันที>>>\r\n***** หรือ เลือก โปรแกรม พัก 2คืน/3คืน พักโรงแรมธีมฉางหลง\r\nเดินทางโดยเที่ยวบิน Air Macao Full Service\r\nNX9989  BKKMFM 0705 1105\r\nNX  992   MFMBKK 1950-2150หรือ\r\nNX9990  MFMBKK 0005-0150 \r\n****3วัน2คืน Collective  บุฟเฟ่ต์ 3มื้อ+เล่น2สวนสนุก+ชมโชว์ Chimelong Hengquin\r\n10-12 ธ.ค. เริ่ม 16,900 บ. \r\n29-31ธ.ค. เริ่ม 23,900 บ.\r\n30-1  ม.ค. เริ่ม 24,900 บ.\r\n2-4  ม.ค.  เริ่ม 22,900 บ.\r\n****4วัน3คืน Collective บุฟเฟ่ต์ 4มื้อ+เล่น2สวนสนุก+ชมโชว์ Chimelong Hengquin\r\n30-2  ม.ค. เริ่ม 28,900\r\n1-4  ม.ค.  เริ่ม  28,900\r\n2-5  ม.ค.  เริ่ม 23,900\r\n( เด็ก ท่านที่3 ลด 1000 บ )',	'',	'',	NULL,	NULL,	NULL,	'None',	'APT',	NULL,	'12:00:00',	NULL,	'',	'',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 1.0, \"price\": 0.0, \"amount\": 0.0}]',	0.00,	'THB',	'2025-11-29 12:00:00',	'2025-12-29',	'2025-11-29 09:08:09',	'2025-11-29 10:30:41',	'NDV8MTc2NDQxMDkxM3wxfDE3Nzc1MDcyMDAupcdZtXaqF_Y-E_rVtHLh3iWWk8FPiU_tPdw',	1,	5,	NULL,	NULL),
