(51,	31,	'251201ELY7',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'package',	'draft',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'2026-01-01',	'2026-01-04',	NULL,	NULL,	4,	0,	4,	0,	'[\"N/A\"]',	'Piyachat20260101',	NULL,	'Chimelong Macau Daily Special 3Nights 4Days\r\nเดินทาง 1-4 มกราคม 2569\r\nสำหรับ 4ผู้ใหญ่\r\n\r\nDay1: กรุงเทพฯ-มาเก๊า-จูไห่\r\nถึงสนามบินมาเก๊า รถท้องถิ่นรับจากสนามบินมาเก๊า ส่งที่ Chimelong Spaceship Hotel\r\nเดินทางสู่ Chimelong Spaceship Hotel\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\n+เย็น ชมแกรนด์โชว์ Chimelong Hengqin\r\n+บุฟเฟต์อาหารค่ำ*** \r\nพัก Chimelong Spaceship Hotel\r\n\r\n------\r\nDay2: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\n+บุฟเฟต์อาหารกลางวัน***\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay3: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nพัก Chimelong Spaceship Hotel\r\n------\r\nDay4: สิทธิเข้าสวนสนุกก่อนใคร 1ชั่วโมง บัตรเข้า 2 สวนสนุก\r\nรวมบุฟเฟต์อาหารเช้า***\r\n+รวมบัตรเข้าสวนสนุก Ocean Kingdom\r\n+รวมบัตรเข้าสวนสนุก Spaceship Park\r\nตามเวลานัดหมาย รถท้องถิ่นนำท่านเดินทางสู่สนามบินมาเก๊า\r\n\r\nAir Macau\r\nNX9989 01JAN BKKMFM 07:05-11:05\r\nNX992   04JAN MFMBKK 19:50-21:50\r\nน้ำหนักโหลด 32KG 1 ใบและ Carry on 7KG\r\n\r\nพัก 2 ท่านต่อห้อง 28,900 บาท/ท่าน',	NULL,	NULL,	NULL,	NULL,	NULL,	'None',	'MFM',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 1, \"price\": 0.0, \"amount\": 0.0}]',	0.00,	NULL,	'2026-01-01 12:00:00',	NULL,	'2025-12-01 04:38:41',	'2025-12-01 06:43:07',	'NTF8MTc2NDU2MzkyNHwxfDE3Nzc4NTI4MDAuUff99bQbFUb6f7qWqlflfrqLd2zvDm72eYg',	1,	4,	NULL,	NULL),
