(73,	53,	'251202IBIB',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'package',	'draft',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'2026-03-26',	'2026-03-29',	NULL,	NULL,	2,	1,	3,	0,	'[\"CHATPORNVORARUX/SUNSANEE MISS\", \"PROHSOONTRON/LALINA MISS*p-c06 DOB11APR19\", \"PROHSOONTRON/SARAN MR\"]',	'AR03885183',	NULL,	'Chimelong Package Daily Special 3Nights 4Days\r\nเดินทาง 26-29 MAR2026\r\n26MAR: กรุงเทพฯ-มาเก๊า\r\nรถส่วนตัวบริการจากสนามบินมาเก๊า ส่ง Chimelong Spaceship Hotel\r\nบัตรเข้า Spaceship Park และ บัตรเข้า Ocean Kingdom\r\n+ บัตรชมโชว์ Chimelong Show***\r\n+บุฟเฟต์อาหารค่ำ***\r\nพักที่ Chimelong Spaceship Hotel\r\n----------\r\n27MAR: สิทธิเข้าสวนสนุกก่อนเปิด 1ชม\r\nบัตรเข้า Spaceship Park และ บัตรเข้า Ocean Kingdom\r\n+บุฟเฟต์อาหารกลางวัน***\r\nพักที่ Chimelong Spaceship Hotel\r\n----------\r\n28MAR: +บุฟเฟต์อาหารเช้าที่โรงแรมเพนกวิน***สิทธิเข้าสวนสนุกก่อนเปิด 1ชม\r\nบัตรเข้า Spaceship Park และ บัตรเข้า Ocean Kingdom\r\nพักที่ Chimelong Spaceship Hotel\r\n----------\r\n29MAR: สิทธิเข้าสวนสนุกก่อนเปิด 1ชม\r\nบัตรเข้า Spaceship Park และ บัตรเข้า Ocean Kingdom\r\nตามเวลานัดหมายรถส่วนตัวรับจาก Spaceship Hotel เดินทางสู่สนามบินมาเก๊า',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'<p>NX  995  26MAR BKKMFM  10:35-14:25<br>NX  992  29MAR MFMBKK  19:45-21:50</p>',	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	NULL,	'[{\"name\": \"ADT\", \"quantity\": 2, \"price\": 20550.0, \"amount\": 41100.0}, {\"name\": \"CHD No Bed\", \"quantity\": 1, \"price\": 19550.0, \"amount\": 19550.0}]',	60650.00,	NULL,	'2026-03-26 12:00:00',	NULL,	'2025-12-02 11:24:47',	'2025-12-02 11:24:47',	'NzN8MTc2NDY4NjU1M3wxfDE3ODUxMTA0MDAuGmMFBV_AWZW4aAYpsUvsr-4LNnaHlRIUj94',	1,	4,	NULL,	NULL);
